package mcpclient

import (
	"context"
	"errors"
	"io"
	"net/http"
	"net/url"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

type redirectTransport func(*http.Request) (*http.Response, error)

func (fn redirectTransport) RoundTrip(r *http.Request) (*http.Response, error) { return fn(r) }

func TestAutomaticAuthRedirects(t *testing.T) {
	for _, target := range []string{"https://other.example/mcp", "http://chatgpt.com/mcp", "https://chatgpt.com:444/mcp", "https://chatgpt.com/next"} {
		t.Run(target, func(t *testing.T) {
			for _, notification := range []bool{false, true} {
				calls := 0
				original := &http.Client{Transport: redirectTransport(func(r *http.Request) (*http.Response, error) {
					calls++
					if calls == 1 {
						return &http.Response{StatusCode: 307, Header: http.Header{"Location": []string{target}}, Body: io.NopCloser(strings.NewReader(""))}, nil
					}
					require.Equal(t, "https://chatgpt.com/next", r.URL.String())
					require.Equal(t, "Bearer token", r.Header.Get("Authorization"))
					return &http.Response{StatusCode: 200, Header: make(http.Header), Body: io.NopCloser(strings.NewReader(`{"result":{}}`))}, nil
				})}
				c, err := New(Options{Endpoint: "https://chatgpt.com/mcp", AccessToken: "token", AccountID: "account", HTTPClient: original, RestrictAuthOrigin: true})
				require.NoError(t, err)
				if notification {
					err = c.notify(context.Background(), "notifications/initialized", nil)
				} else {
					err = c.call(context.Background(), "tools/list", nil, &struct{}{})
				}
				if target == "https://chatgpt.com/next" {
					require.NoError(t, err)
					require.Equal(t, 2, calls)
				} else {
					require.ErrorContains(t, err, "credential origin")
					require.Equal(t, 1, calls)
				}
				require.Nil(t, original.CheckRedirect)
			}
		})
	}
}

func TestAutomaticAuthRedirectCallerPolicy(t *testing.T) {
	callerError := errors.New("caller declined redirect: " + diagnosticCanary)
	for _, tc := range []struct {
		name, target string
		callbackErr  error
		wantCalls    int
	}{
		{"changed origin", "https://other.example/mcp", nil, 1},
		{"downgrade", "http://chatgpt.com/mcp", nil, 1},
		{"userinfo", "https://user@chatgpt.com/mcp", nil, 1},
		{"same origin", "https://chatgpt.com/rewritten", nil, 2},
		{"caller error", "https://other.example/mcp", callerError, 1},
	} {
		t.Run(tc.name, func(t *testing.T) {
			for _, notification := range []bool{false, true} {
				calls, callbacks := 0, 0
				client := &http.Client{
					CheckRedirect: func(req *http.Request, via []*http.Request) error {
						callbacks++
						changed, err := url.Parse(tc.target)
						require.NoError(t, err)
						req.URL = changed
						return tc.callbackErr
					},
					Transport: redirectTransport(func(r *http.Request) (*http.Response, error) {
						calls++
						if calls == 1 {
							return &http.Response{StatusCode: 307, Header: http.Header{"Location": {"https://chatgpt.com/next"}}, Body: io.NopCloser(strings.NewReader(""))}, nil
						}
						require.Equal(t, "https://chatgpt.com/rewritten", r.URL.String())
						require.Equal(t, "Bearer token", r.Header.Get("Authorization"))
						require.Equal(t, "account", r.Header.Get("ChatGPT-Account-ID"))
						return &http.Response{StatusCode: 200, Header: make(http.Header), Body: io.NopCloser(strings.NewReader(`{"result":{}}`))}, nil
					}),
				}
				c, err := New(Options{Endpoint: "https://chatgpt.com/mcp", AccessToken: "token", AccountID: "account", HTTPClient: client, RestrictAuthOrigin: true})
				require.NoError(t, err)
				if notification {
					err = c.notify(context.Background(), "notifications/initialized", nil)
				} else {
					err = c.call(context.Background(), "tools/list", nil, &struct{}{})
				}
				if tc.callbackErr != nil {
					require.ErrorIs(t, err, tc.callbackErr)
					assertSafeDiagnostic(t, err)
				} else if tc.wantCalls == 1 {
					require.ErrorContains(t, err, "credential origin")
				} else {
					require.NoError(t, err)
				}
				require.Equal(t, tc.wantCalls, calls)
				require.Equal(t, 1, callbacks)
			}
		})
	}
	c, err := New(Options{Endpoint: "https://chatgpt.com/mcp", RestrictAuthOrigin: true})
	require.NoError(t, err)
	req, err := http.NewRequest(http.MethodGet, "https://chatgpt.com/next", nil)
	require.NoError(t, err)
	require.ErrorContains(t, c.httpClient.CheckRedirect(req, make([]*http.Request, 10)), "stopped after 10 redirects")
}

package cli

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"sync"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	"github.com/openclaw/slacrawl/internal/config"
	"github.com/openclaw/slacrawl/internal/share"
	"github.com/openclaw/slacrawl/internal/store"
)

func TestMCPSlicedReturnedRootEvidenceFromCLI(t *testing.T) {
	for _, source := range []string{"mcp", "connector"} {
		for _, mode := range []string{"root-child", "child-root", "root-page", "child-page", "retained-child", "child-only", "priority-child"} {
			t.Run(source+"/"+mode, func(t *testing.T) {
				ctx := context.Background()
				fixture := &mcpReconcileFixture{}
				cfg, path := mcpReconcileConfig(t, fixture)
				st, err := store.Open(cfg.DBPath)
				require.NoError(t, err)
				now := time.Unix(1700000000, 0).UTC()
				mcpReconcileCatalog(t, st, now)
				old := store.Message{WorkspaceID: "TLOCAL", ChannelID: "C123", TS: mcpWorkRoot, Text: "old retained root", NormalizedText: "old retained root", ReplyCount: 1, SourceName: "mcp", SourceRank: 4, RawJSON: "{}", UpdatedAt: now}
				require.NoError(t, st.UpsertMessage(ctx, old, nil))
				_, err = st.PrepareThreadWork(ctx, "mcp", "TLOCAL", "C123", nil)
				require.NoError(t, err)
				beforePending := mcpWorkPending(t, st)
				beforeRoot := apiKeyRows(t, st, "select * from messages where ts='"+mcpWorkRoot+"'")
				fixture.mu.Lock()
				root := mcpWorkMessage(mcpWorkNewRoot, "", false)
				child := mcpWorkMessage(mcpWorkNewChild, mcpWorkNewRoot, false)
				fixture.messages = []map[string]any{root, child}
				switch mode {
				case "child-root":
					fixture.messages = []map[string]any{child, root}
				case "root-page", "child-page":
					first, last := root, child
					if mode == "child-page" {
						first, last = child, root
					}
					fixture.messages = []map[string]any{first}
					for i := 0; i < 499; i++ {
						fixture.messages = append(fixture.messages, mcpWorkMessage(fmt.Sprintf("171000%04d.000000", 2000+i), "", false))
					}
					fixture.messages = append(fixture.messages, last)
				case "retained-child", "priority-child":
					retained := store.Message{WorkspaceID: "TLOCAL", ChannelID: "C123", TS: mcpWorkNewChild, ThreadTS: mcpWorkNewRoot, Text: "retained child", NormalizedText: "retained child", SourceName: "mcp", SourceRank: 4, RawJSON: "{}", UpdatedAt: now}
					if mode == "priority-child" {
						retained.ThreadTS, retained.SourceName, retained.SourceRank = "", "api-user", 1
					}
					require.NoError(t, st.UpsertMessage(ctx, retained, nil))
					if mode == "retained-child" {
						fixture.messages = fixture.messages[:1]
					}
				case "child-only":
					child["thread_ts"] = mcpWorkRoot
					fixture.messages = []map[string]any{child}
				}
				fixture.mu.Unlock()
				require.NoError(t, st.Close())
				beforeConfig, err := os.ReadFile(path)
				require.NoError(t, err)
				args := []string{"--config", path, "--json", "sync", "--source", source, "--workspace", "TLOCAL", "--channels", "C123", "--with-media=false", "--since", mcpWorkSince}
				if mode == "child-root" || mode == "child-page" || mode == "priority-child" {
					args = append(args, "--full")
				}
				var stdout, stderr bytes.Buffer
				err = (&App{Stdout: &stdout, Stderr: &stderr}).Run(ctx, args)
				require.NoError(t, err)
				require.NotEmpty(t, stdout.String())
				calls, serverErrors := fixture.observed()
				require.Empty(t, serverErrors)
				want := []mcpCoverageCall{{"slack_list_channels", map[string]any{"limit": float64(20)}}, {"slack_get_channel_history", map[string]any{"channel_id": "C123", "limit": float64(501)}}}
				if mode != "child-only" && mode != "priority-child" {
					want = append(want, mcpCoverageCall{"slack_get_thread_replies", map[string]any{"channel_id": "C123", "thread_ts": mcpWorkNewRoot}})
				}
				require.Equal(t, want, calls)
				st, err = store.OpenReadOnly(cfg.DBPath)
				require.NoError(t, err)
				defer func() { require.NoError(t, st.Close()) }()
				require.Equal(t, beforePending, mcpWorkPending(t, st), "Since and FullSince leave every unselected queue field unchanged")
				require.Equal(t, beforeRoot, apiKeyRows(t, st, "select * from messages where ts='"+mcpWorkRoot+"'"))
				replies := apiKeyRows(t, st, "select coalesce(thread_ts,'') as thread_ts,source_name,source_rank from messages where ts='1710001003.000000'")
				if len(want) == 3 {
					require.Equal(t, []map[string]any{{"thread_ts": mcpWorkNewRoot, "source_name": "mcp", "source_rank": int64(4)}}, replies)
				} else {
					require.Empty(t, replies)
				}
				require.Equal(t, apiKeyRows(t, st, "select channel_id || '|' || ts as message_key from messages order by message_key"), apiKeyRows(t, st, "select message_key from message_fts order by message_key"))
				afterConfig, err := os.ReadFile(path)
				require.NoError(t, err)
				require.Equal(t, beforeConfig, afterConfig)
			})
		}
	}
}

func TestMCPSlicedRepliesOwnSelectedJobsFromCLI(t *testing.T) {
	for _, source := range []string{"mcp", "connector"} {
		for _, full := range []bool{false, true} {
			for _, mode := range []string{"complete", "empty", "more", "limited", "error"} {
				t.Run(fmt.Sprintf("%s/full=%t/%s", source, full, mode), func(t *testing.T) {
					ctx := context.Background()
					const laterRoot = "1710002001.000000"
					fixture := &mcpReconcileFixture{messages: []map[string]any{
						mcpWorkMessage(mcpWorkNewRoot, "", true), mcpWorkMessage(laterRoot, "", true),
					}}
					cfg, path := mcpReconcileConfig(t, fixture)
					st, err := store.Open(cfg.DBPath)
					require.NoError(t, err)
					defer func() { require.NoError(t, st.Close()) }()
					now := time.Unix(1700000000, 0).UTC()
					mcpReconcileCatalog(t, st, now)
					for _, ts := range []string{mcpWorkRoot, mcpWorkNewRoot} {
						require.NoError(t, st.UpsertMessage(ctx, store.Message{WorkspaceID: "TLOCAL", ChannelID: "C123", TS: ts, Text: "retained", NormalizedText: "retained", ReplyCount: 1, SourceName: "mcp", SourceRank: 4, RawJSON: "{}", UpdatedAt: now}, nil))
					}
					_, err = st.ApplyWriteBatch(ctx, store.WriteBatch{PendingThreads: []store.ThreadWork{
						{SourceName: "mcp", WorkspaceID: "TLOCAL", ChannelID: "C123", TS: mcpWorkRoot},
						{SourceName: "mcp", WorkspaceID: "TLOCAL", ChannelID: "C123", TS: mcpWorkNewRoot},
						{SourceName: "api-user", WorkspaceID: "TLOCAL", ChannelID: "C123", TS: mcpWorkNewRoot},
					}})
					require.NoError(t, err)
					require.NoError(t, st.SetSyncState(ctx, "api-user", "thread_skip", "TLOCAL|C123|"+mcpWorkNewRoot, "unrelated API work"))
					require.NoError(t, st.SetSyncState(ctx, "mcp", "workspace", "TLOCAL", "prior-success"))
					beforePending := mcpWorkPending(t, st)
					beforeAPI := apiKeyRows(t, st, "select * from sync_state where source_name='api-user' order by entity_type,entity_id")
					beforeWorkspace := mcpWorkWorkspace(t, st)
					beforeRoot := apiKeyRows(t, st, "select * from messages where ts='"+mcpWorkRoot+"'")
					beforeConfig, err := os.ReadFile(path)
					require.NoError(t, err)
					observed := make(chan []map[string]any, 1)
					fixture.mu.Lock()
					fixture.reply = func(root string) map[string]any {
						if root != mcpWorkNewRoot && root != laterRoot {
							t.Errorf("unexpected selected root %q", root)
							return map[string]any{"ok": false, "error": "unexpected_root"}
						}
						if root == mcpWorkNewRoot {
							select {
							case observed <- mcpWorkPending(t, st):
							default:
								t.Error("selected root was requested more than once")
							}
						}
						messages := []map[string]any{}
						if mode != "empty" {
							child := "1710001003.000000"
							if root == laterRoot {
								child = "1710002002.000000"
							}
							messages = []map[string]any{mcpWorkMessage(root, "", false), mcpWorkMessage(child, root, false)}
						}
						payload := map[string]any{"ok": true, "messages": messages}
						if root == mcpWorkNewRoot {
							switch mode {
							case "more":
								payload["has_more"] = true
							case "limited":
								payload["is_limited"] = true
							case "error":
								payload["ok"], payload["error"] = false, "synthetic_scoped_failure"
								payload["messages"] = []map[string]any{{"ts": "1710001003.000000", "text": "SCOPED_REJECTED_CANARY"}}
							}
						}
						return payload
					}
					fixture.mu.Unlock()
					args := []string{"--config", path, "--json", "sync", "--source", source, "--workspace", "TLOCAL", "--channels", "C123", "--with-media=false", "--since", mcpWorkSince}
					if full {
						args = append(args, "--full")
					}
					var stdout, stderr bytes.Buffer
					runErr := (&App{Stdout: &stdout, Stderr: &stderr}).Run(ctx, args)
					if mode == "complete" || mode == "empty" {
						require.NoError(t, runErr)
						require.NotEmpty(t, stdout.String())
						require.NotEqual(t, beforeWorkspace, mcpWorkWorkspace(t, st))
					} else {
						require.Error(t, runErr)
						require.Empty(t, stdout.String())
						require.Equal(t, beforeWorkspace, mcpWorkWorkspace(t, st))
						if mode == "more" {
							require.EqualError(t, runErr, mcpWorkMoreError)
						} else if mode == "limited" {
							require.EqualError(t, runErr, mcpWorkLimitedError)
						} else {
							require.ErrorContains(t, runErr, "read MCP thread")
						}
					}
					require.Len(t, observed, 1, "acquisition finishes for both selected roots before the first reply request")
					acquired := <-observed
					require.Len(t, acquired, 3)
					byKey := map[string]map[string]any{}
					for _, row := range acquired {
						byKey[row["entity_id"].(string)] = row
					}
					oldKey := retainedCLIKey("TLOCAL", "C123", mcpWorkRoot)
					firstKey := retainedCLIKey("TLOCAL", "C123", mcpWorkNewRoot)
					laterKey := retainedCLIKey("TLOCAL", "C123", laterRoot)
					require.Equal(t, beforePending[0], byKey[oldKey])
					require.NotEqual(t, beforePending[1]["value"], byKey[firstKey]["value"], "Since deliberately renews selected existing work")
					require.NotNil(t, byKey[laterKey])
					expected := []map[string]any{byKey[oldKey]}
					if mode == "more" || mode == "limited" || mode == "error" {
						expected = append(expected, byKey[firstKey])
					}
					if mode == "error" {
						expected = append(expected, byKey[laterKey])
					}
					require.Equal(t, expected, mcpWorkPending(t, st), "errors retain even selected roots not reached; complete/empty replies retire their exact jobs")
					require.Equal(t, beforeAPI, apiKeyRows(t, st, "select * from sync_state where source_name='api-user' order by entity_type,entity_id"))
					require.Equal(t, beforeRoot, apiKeyRows(t, st, "select * from messages where ts='"+mcpWorkRoot+"'"))
					calls, serverErrors := fixture.observed()
					require.Empty(t, serverErrors)
					want := []mcpCoverageCall{
						{"slack_list_channels", map[string]any{"limit": float64(20)}},
						{"slack_get_channel_history", map[string]any{"channel_id": "C123", "limit": float64(501)}},
						{"slack_get_thread_replies", map[string]any{"channel_id": "C123", "thread_ts": mcpWorkNewRoot}},
					}
					if mode != "error" {
						want = append(want, mcpCoverageCall{"slack_get_thread_replies", map[string]any{"channel_id": "C123", "thread_ts": laterRoot}})
					}
					require.Equal(t, want, calls, "replies contain no Since/oldest argument and unselected backlog is not fetched")
					require.Equal(t, apiKeyRows(t, st, "select channel_id || '|' || ts as message_key from messages order by message_key"), apiKeyRows(t, st, "select message_key from message_fts order by message_key"))
					for _, table := range []string{"messages", "message_events", "message_event_heads", "message_mentions", "message_fts"} {
						require.NotContains(t, fmt.Sprint(apiKeyRows(t, st, "select * from "+table)), "SCOPED_REJECTED_CANARY")
					}
					afterConfig, err := os.ReadFile(path)
					require.NoError(t, err)
					require.Equal(t, beforeConfig, afterConfig)
				})
			}
		}
	}
}

func TestMCPNoToolReconcilesMergedTombstonesFromCLI(t *testing.T) {
	for _, source := range []string{"mcp", "connector"} {
		for _, mode := range []string{"deleted_ts", "subtype", "live", "fresh", "history-error", "since", "full-since"} {
			t.Run(source+"/"+mode, func(t *testing.T) {
				ctx := context.Background()
				fixture := &mcpReconcileFixture{noTool: true, historyError: mode == "history-error"}
				cfg, path := mcpReconcileConfig(t, fixture)
				st, err := store.Open(cfg.DBPath)
				require.NoError(t, err)
				now := time.Unix(1700000000, 0).UTC()
				mcpReconcileCatalog(t, st, now)
				root := store.Message{WorkspaceID: "TLOCAL", ChannelID: "C123", TS: mcpWorkRoot, Text: "root", NormalizedText: "root", ReplyCount: 1, SourceName: "mcp", SourceRank: 4, RawJSON: "{}", UpdatedAt: now}
				require.NoError(t, st.UpsertMessage(ctx, root, nil))
				require.NoError(t, st.SetSyncState(ctx, "mcp", "workspace", "TLOCAL", "2020-01-01T00:00:00Z"))
				if mode != "fresh" {
					_, err := st.PrepareThreadWork(ctx, "mcp", "TLOCAL", "C123", nil)
					require.NoError(t, err)
				}
				beforePending := mcpWorkPending(t, st)
				beforeWorkspace := mcpWorkWorkspace(t, st)
				if mode != "live" && mode != "fresh" {
					donor, err := store.Open(filepath.Join(t.TempDir(), "donor.db"))
					require.NoError(t, err)
					mcpReconcileCatalog(t, donor, now)
					deleted := root
					deleted.ReplyCount, deleted.UpdatedAt = 0, now.Add(time.Hour)
					if mode == "subtype" {
						deleted.Subtype = "message_deleted"
					} else {
						deleted.DeletedTS = "1710000009.000000"
					}
					require.NoError(t, donor.UpsertMessage(ctx, deleted, nil))
					opts := share.Options{RepoPath: filepath.Join(t.TempDir(), "share")}
					_, err = share.Export(ctx, donor, opts)
					require.NoError(t, err)
					_, err = share.Import(ctx, st, opts)
					require.NoError(t, err)
					require.NoError(t, donor.Close())
					require.Equal(t, beforePending, mcpWorkPending(t, st), "share merge leaves local progress for its lifecycle owner")
					require.Equal(t, []map[string]any{{"deleted_ts": deleted.DeletedTS, "subtype": deleted.Subtype, "reply_count": int64(0)}}, apiKeyRows(t, st, "select coalesce(deleted_ts,'') as deleted_ts,coalesce(subtype,'') as subtype,reply_count from messages"))
				}
				messagesBefore := apiKeyRows(t, st, "select * from messages")
				require.NoError(t, st.Close())
				beforeConfig, err := os.ReadFile(path)
				require.NoError(t, err)
				args := []string{"--config", path, "--json", "sync", "--source", source, "--workspace", "TLOCAL", "--channels", "C123", "--with-media=false"}
				if mode == "since" || mode == "full-since" {
					args = append(args, "--since", mcpWorkSince)
				}
				if mode == "full-since" {
					args = append(args, "--full")
				}
				for attempt := 0; attempt < 2; attempt++ {
					fixture.resetCalls()
					var stdout, stderr bytes.Buffer
					runErr := (&App{Stdout: &stdout, Stderr: &stderr}).Run(ctx, args)
					failed := mode == "live" || mode == "history-error"
					if mode == "live" {
						require.EqualError(t, runErr, mcpWorkToolError)
					} else if mode == "history-error" {
						require.ErrorContains(t, runErr, "Slack API reported an error")
					} else {
						require.NoError(t, runErr)
					}
					require.Equal(t, !failed, stdout.Len() != 0)
					calls, serverErrors := fixture.observed()
					require.Empty(t, serverErrors)
					require.Equal(t, []mcpCoverageCall{{"slack_list_channels", map[string]any{"limit": float64(20)}}, {"slack_get_channel_history", map[string]any{"channel_id": "C123", "limit": float64(501)}}}, calls)
					st, err = store.OpenReadOnly(cfg.DBPath)
					require.NoError(t, err)
					pending := mcpWorkPending(t, st)
					if mode == "deleted_ts" || mode == "subtype" || mode == "fresh" {
						require.Empty(t, pending)
					} else {
						require.Equal(t, beforePending, pending)
					}
					if failed {
						require.Equal(t, beforeWorkspace, mcpWorkWorkspace(t, st))
					} else {
						require.NotEqual(t, beforeWorkspace, mcpWorkWorkspace(t, st))
					}
					require.Equal(t, messagesBefore, apiKeyRows(t, st, "select * from messages"))
					require.NoError(t, st.Close())
				}
				afterConfig, err := os.ReadFile(path)
				require.NoError(t, err)
				require.Equal(t, beforeConfig, afterConfig)
			})
		}
	}
}

func mcpReconcileCatalog(t *testing.T, st *store.Store, now time.Time) {
	t.Helper()
	ctx := context.Background()
	require.NoError(t, st.UpsertWorkspace(ctx, store.Workspace{ID: "TLOCAL", Name: "fixture", RawJSON: "{}", UpdatedAt: now}))
	require.NoError(t, st.UpsertChannel(ctx, store.Channel{ID: "C123", WorkspaceID: "TLOCAL", Name: "fixture", Kind: "public_channel", RawJSON: "{}", UpdatedAt: now}))
}

func mcpReconcileConfig(t *testing.T, fixture *mcpReconcileFixture) (config.Config, string) {
	t.Helper()
	cfg, path := userPrimaryConfig(t)
	cfg.Slack.Bot.Enabled, cfg.Slack.User.Enabled, cfg.Slack.App.Enabled = false, false, false
	cfg.Sync.IncludeDMs = new(false)
	server := httptest.NewServer(http.HandlerFunc(fixture.serveHTTP))
	t.Cleanup(server.Close)
	cfg.Slack.MCP.Enabled, cfg.Slack.MCP.Transport, cfg.Slack.MCP.BaseURL = true, "http", server.URL
	cfg.Slack.MCP.TokenEnv, cfg.Slack.MCP.AccountIDEnv = "SLACRAWL_RECONCILE_TOKEN", "SLACRAWL_RECONCILE_ACCOUNT"
	cfg.Slack.MCP.ConnectorID = ""
	cfg.Slack.MCP.PageSize, cfg.Slack.MCP.SearchLimit, cfg.Slack.MCP.MaxPages = 501, 20, 1
	t.Setenv(cfg.Slack.MCP.TokenEnv, "synthetic-reconcile-token")
	t.Setenv(cfg.Slack.MCP.AccountIDEnv, "")
	require.NoError(t, cfg.Save(path))
	return cfg, path
}

type mcpReconcileFixture struct {
	mu                   sync.Mutex
	messages             []map[string]any
	noTool, historyError bool
	reply                func(string) map[string]any
	calls                []mcpCoverageCall
	errors               []string
}

func (f *mcpReconcileFixture) observed() ([]mcpCoverageCall, []string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]mcpCoverageCall{}, f.calls...), append([]string{}, f.errors...)
}

func (f *mcpReconcileFixture) resetCalls() {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.calls = nil
}

func (f *mcpReconcileFixture) serveHTTP(w http.ResponseWriter, r *http.Request) {
	var req struct {
		ID     json.RawMessage
		Method string
		Params struct {
			Name      string
			Arguments map[string]any
		}
	}
	fail := func(reason string) {
		f.mu.Lock()
		f.errors = append(f.errors, reason)
		f.mu.Unlock()
		http.Error(w, "synthetic fixture rejected request", http.StatusBadRequest)
	}
	if r.Header.Get("Authorization") != "[REDACTED]" {
		fail("unexpected credential")
		return
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		fail("invalid JSON")
		return
	}
	var result any
	switch req.Method {
	case "initialize":
		result = map[string]any{"protocolVersion": "2025-03-26"}
	case "notifications/initialized":
		w.WriteHeader(http.StatusAccepted)
		return
	case "tools/list":
		names := []string{"slack_list_channels", "slack_get_users", "slack_get_channel_history"}
		if !f.noTool {
			names = append(names, "slack_get_thread_replies")
		}
		tools := []map[string]any{}
		for _, name := range names {
			tools = append(tools, map[string]any{"name": name})
		}
		result = map[string]any{"tools": tools}
	case "tools/call":
		f.mu.Lock()
		f.calls = append(f.calls, mcpCoverageCall{req.Params.Name, req.Params.Arguments})
		f.mu.Unlock()
		payload := map[string]any{"ok": true}
		switch req.Params.Name {
		case "slack_list_channels":
			payload["channels"] = []map[string]any{{"id": "C123", "name": "fixture", "is_channel": true}}
		case "slack_get_channel_history":
			if req.Params.Arguments["limit"] != float64(501) {
				fail("history page size")
				return
			}
			f.mu.Lock()
			messages := f.messages
			f.mu.Unlock()
			if messages == nil {
				messages = []map[string]any{}
			}
			payload["messages"] = messages
			if f.historyError {
				payload["ok"], payload["error"] = false, "synthetic_history_error"
			}
		case "slack_get_thread_replies":
			root, _ := req.Params.Arguments["thread_ts"].(string)
			f.mu.Lock()
			reply := f.reply
			f.mu.Unlock()
			if reply != nil {
				payload = reply(root)
				break
			}
			if root != mcpWorkRoot && root != mcpWorkNewRoot {
				fail("unexpected thread")
				return
			}
			payload["messages"] = []map[string]any{mcpWorkMessage(root, "", false), mcpWorkMessage("1710001003.000000", root, false)}
		default:
			fail("unexpected tool")
			return
		}
		raw, err := json.Marshal(payload)
		if err != nil {
			fail("marshal response")
			return
		}
		result = map[string]any{"content": []map[string]any{{"type": "text", "text": string(raw)}}}
	default:
		fail("unexpected method")
		return
	}
	if err := json.NewEncoder(w).Encode(map[string]any{"jsonrpc": "2.0", "id": req.ID, "result": result}); err != nil {
		f.mu.Lock()
		f.errors = append(f.errors, "response write")
		f.mu.Unlock()
	}
}

