const diagnosticCanary = "SYNTHETIC_PRIVATE_MCP_CONTENT"
const diagnosticNumber = "867530912345678901234567890"

func TestResponseDiagnosticsExcludeServerContent(t *testing.T) {
	for _, transport := range []string{"http", "stdio"} {
		for _, tc := range []struct {
			name, response, want string
			list                 bool
		}{
			{"RPC error", `{"id":1,"error":{"code":-32603,"message":"` + diagnosticCanary + `","data":{"private":"` + diagnosticCanary + `"}}}`, "JSON-RPC error -32603", false},
			{"invalid envelope", `{"id":1,"error":{"code":` + diagnosticNumber + `}}`, "JSON-RPC response", false},
			{"invalid result", `{"id":1,"result":{"isError":` + diagnosticNumber + `}}`, "result: invalid response", false},
			{"tool error", `{"id":1,"result":{"isError":true,"content":[{"type":"text","text":"` + diagnosticCanary + `"}]}}`, "tools/call reported an error", false},
			{"empty tool error", `{"id":1,"result":{"isError":true}}`, "tools/call reported an error", false},
			{"empty tool result", `{"id":1,"result":{"content":[]}}`, "tools/call returned no text content", false},
			{"repeated cursor", `{"id":1,"result":{"tools":[],"nextCursor":"` + diagnosticCanary + `"}}`, "tools/list repeated cursor", true},
		} {
			t.Run(transport+"/"+tc.name, func(t *testing.T) {
				ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
				defer cancel()
				var client Session
				if transport == "http" {
					server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
						_, err := io.WriteString(w, tc.response)
						require.NoError(t, err)
					}))
					defer server.Close()
					var err error
					client, err = New(Options{Endpoint: server.URL})
					require.NoError(t, err)
				} else {
					var err error
					client, err = NewStdio(ctx, StdioOptions{
						Command: os.Args[0], Args: []string{"-test.run=^TestDiagnosticsStdioHelper$"},
						Env: []string{"MCP_DIAGNOSTIC_RESPONSE=" + tc.response},
					})
					require.NoError(t, err)
				}
				defer func() { require.NoError(t, client.Close()) }()
				var err error
				if tc.list {
					_, err = client.ListTools(ctx)
				} else {
					var text string
					text, err = client.CallToolText(ctx, diagnosticCanary, nil)
					require.Empty(t, text)
				}
				require.ErrorContains(t, err, tc.want)
				assertSafeDiagnostic(t, err)
			})
		}
	}
}

func TestDiagnosticsStdioHelper(t *testing.T) {
	response := os.Getenv("MCP_DIAGNOSTIC_RESPONSE")
	if response == "" {
		return
	}
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		var request struct {
			ID json.RawMessage `json:"id"`
		}
		require.NoError(t, json.Unmarshal(scanner.Bytes(), &request))
		var packet map[string]json.RawMessage
		require.NoError(t, json.Unmarshal([]byte(response), &packet))
		packet["id"] = request.ID
		_, err := fmt.Fprintln(os.Stderr, diagnosticCanary)
		require.NoError(t, err)
		require.NoError(t, json.NewEncoder(os.Stdout).Encode(packet))
	}
	require.NoError(t, scanner.Err())
}

func TestHTTPDiagnosticsExcludeBodiesAndRedirects(t *testing.T) {
	for _, notification := range []bool{false, true} {
		for _, tc := range []struct{ name, location, want string }{
			{"HTTP failure", "", "HTTP 503"},
			{"origin redirect", "https://other.example/" + diagnosticCanary, "credential origin"},
			{"invalid redirect", "/%" + diagnosticCanary, "request failed"},
		} {
			t.Run(fmt.Sprintf("%s/notification=%v", tc.name, notification), func(t *testing.T) {
				calls := 0
				server := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
					calls++
					if tc.location != "" {
						w.Header().Set("Location", tc.location)
						w.WriteHeader(http.StatusTemporaryRedirect)
					} else {
						w.WriteHeader(http.StatusServiceUnavailable)
					}
					_, err := io.WriteString(w, diagnosticCanary)
					require.NoError(t, err)
				}))
				defer server.Close()
				client, err := New(Options{Endpoint: server.URL, HTTPClient: server.Client(), RestrictAuthOrigin: true})
				require.NoError(t, err)
				if notification {
					err = client.notify(context.Background(), "notifications/initialized", nil)
				} else {
					_, err = client.ListTools(context.Background())
				}
				require.ErrorContains(t, err, tc.want)
				assertSafeDiagnostic(t, err)
				require.Equal(t, 1, calls)
			})
		}
	}
}

type diagnosticReader struct{ err error }

func (r diagnosticReader) Read([]byte) (int, error) { return 0, r.err }

func TestHTTPDiagnosticsPreserveErrorIdentity(t *testing.T) {
	for _, notification := range []bool{false, true} {
		for _, readBody := range []bool{false, true} {
			for _, cause := range []error{context.Canceled, context.DeadlineExceeded, errors.New("caller declined redirect")} {
				t.Run(fmt.Sprintf("notification=%v/body=%v/%v", notification, readBody, cause), func(t *testing.T) {
					failure := errors.Join(errors.New(diagnosticCanary), cause)
					client, err := New(Options{Endpoint: "https://server.example/mcp", HTTPClient: &http.Client{
						Transport: redirectTransport(func(*http.Request) (*http.Response, error) {
							if !readBody {
								return nil, failure
							}
							return &http.Response{StatusCode: 200, Header: make(http.Header), Body: io.NopCloser(diagnosticReader{failure})}, nil
						}),
					}})
					require.NoError(t, err)
					if notification {
						err = client.notify(context.Background(), "notifications/initialized", nil)
					} else {
						_, err = client.ListTools(context.Background())
					}
					require.ErrorIs(t, err, cause)
					require.Nil(t, errors.Unwrap(err))
					assertSafeDiagnostic(t, err)
				})
			}
		}
	}
}

func TestToolSuccessContentRemainsUnchanged(t *testing.T) {
	text, err := callToolText(context.Background(), func(_ context.Context, _ string, _ any, out any) error {
		return json.Unmarshal([]byte(`{"content":[{"text":"  `+diagnosticCanary+`  "},{"type":"image","text":"ignored"},{"type":"text","text":"second"}]}`), out)
	}, diagnosticCanary, nil)
	require.NoError(t, err)
	require.Equal(t, "  "+diagnosticCanary+"  \nsecond", text)
}

type diagnosticMarshaler struct{}

func (diagnosticMarshaler) MarshalJSON() ([]byte, error) {
	return nil, errors.New(diagnosticCanary)
}

func TestRequestDiagnosticsExcludeInvalidInputs(t *testing.T) {
	for _, notification := range []bool{false, true} {
		for _, invalidEndpoint := range []bool{false, true} {
			t.Run(fmt.Sprintf("notification=%v/endpoint=%v", notification, invalidEndpoint), func(t *testing.T) {
				endpoint := "https://server.example/mcp"
				var params any = diagnosticMarshaler{}
				if invalidEndpoint {
					endpoint = "https://server.example/%" + diagnosticCanary
					params = nil
				}
				client, err := New(Options{Endpoint: endpoint})
				require.NoError(t, err)
				if notification {
					err = client.notify(context.Background(), "notifications/initialized", params)
				} else {
					err = client.call(context.Background(), "tools/call", params, nil)
				}
				assertSafeDiagnostic(t, err)
			})
		}
	}
	client := &StdioClient{}
	assertSafeDiagnostic(t, client.write(context.Background(), diagnosticMarshaler{}))
}

type diagnosticWriter struct{ err error }

func (w diagnosticWriter) Write([]byte) (int, error) { return 0, w.err }
func (w diagnosticWriter) Close() error              { return nil }

func TestStdioWriteDiagnosticsPreserveErrorIdentity(t *testing.T) {
	cause := errors.Join(errors.New(diagnosticCanary), context.Canceled)
	client := &StdioClient{stdin: diagnosticWriter{cause}}
	err := client.write(context.Background(), map[string]any{"method": "tools/call"})
	require.ErrorIs(t, err, context.Canceled)
	require.Nil(t, errors.Unwrap(err))
	assertSafeDiagnostic(t, err)
}

func assertSafeDiagnostic(t *testing.T, err error) {
	t.Helper()
	require.Error(t, err)
	for _, format := range []string{"%v", "%+v", "%s"} {
		text := fmt.Sprintf(format, err)
		require.NotContains(t, text, diagnosticCanary)
		require.NotContains(t, text, diagnosticNumber)
		require.NotContains(t, strings.ToLower(text), "https://")
	}
}

package cli

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"testing"
	"time"

	"github.com/openclaw/slacrawl/internal/config"
	"github.com/openclaw/slacrawl/internal/store"
	"github.com/stretchr/testify/require"
)

func TestMCPWorkspaceCollisionDiagnosticsAcrossCLIPaths(t *testing.T) {
	const foreignWorkspace = "TCANARYFOREIGN"
	const foreignChannel = "CCANARYFOREIGN"
	const foreignUser = "UCANARYFOREIGN"
	const canary = "synthetic-private-collision-content"
	for _, source := range []string{"mcp", "connector"} {
		for _, collision := range []string{"user", "channel", "message"} {
			t.Run(source+"/"+collision, func(t *testing.T) {
				dir := t.TempDir()
				cfg := config.Default()
				cfg.DBPath = filepath.Join(dir, "archive.db")
				cfg.CacheDir = filepath.Join(dir, "cache")
				cfg.LogDir = filepath.Join(dir, "logs")
				cfg.Share.RepoPath = filepath.Join(dir, "share")
				cfg.Share.AutoUpdate = false
				ctx := context.Background()
				st, err := store.Open(cfg.DBPath)
				require.NoError(t, err)
				now := time.Now().UTC()
				for _, workspace := range []string{"TREQUEST", foreignWorkspace} {
					require.NoError(t, st.UpsertWorkspace(ctx, store.Workspace{ID: workspace, Name: "preserved", RawJSON: "{}", UpdatedAt: now}))
				}
				for _, channel := range []store.Channel{
					{ID: "CLOCAL", WorkspaceID: "TREQUEST", Kind: "public_channel", Name: "preserved", RawJSON: "{}", UpdatedAt: now},
					{ID: foreignChannel, WorkspaceID: foreignWorkspace, Kind: "public_channel", Name: "preserved", RawJSON: "{}", UpdatedAt: now},
				} {
					require.NoError(t, st.UpsertChannel(ctx, channel))
				}
				require.NoError(t, st.UpsertUser(ctx, store.User{ID: foreignUser, WorkspaceID: foreignWorkspace, Name: "preserved", RawJSON: "{}", UpdatedAt: now}))
				require.NoError(t, st.UpsertMessage(ctx, store.Message{
					WorkspaceID: foreignWorkspace, ChannelID: foreignChannel, TS: "1710000000.000001", UserID: foreignUser,
					Text: "preserved", NormalizedText: "preserved", SourceName: "api-user", SourceRank: 1, RawJSON: "{}", UpdatedAt: now,
				}, nil))
				require.NoError(t, st.SetSyncState(ctx, "mcp", "workspace", "TREQUEST", "previous-proof"))
				before := map[string][]map[string]any{}
				for _, table := range []string{"workspaces", "channels", "users", "messages", "message_files", "message_events", "message_event_heads", "message_mentions", "message_fts", "embedding_jobs", "sync_state"} {
					before[table], err = st.QueryReadOnly(ctx, "select * from "+table)
					require.NoError(t, err)
				}
				require.NoError(t, st.Close())

				server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
					var request struct {
						Method string `json:"method"`
						Params struct {
							Name string `json:"name"`
						} `json:"params"`
					}
					require.NoError(t, json.NewDecoder(r.Body).Decode(&request))
					var result any
					switch request.Method {
					case "initialize":
						result = map[string]any{"protocolVersion": "2025-03-26"}
					case "notifications/initialized":
						w.WriteHeader(http.StatusAccepted)
						return
					case "tools/list":
						result = map[string]any{"tools": []map[string]any{{"name": "slack_search_channels"}, {"name": "slack_search_users"}, {"name": "slack_read_channel"}}}
					case "tools/call":
						channelID := "CLOCAL"
						if collision == "channel" {
							channelID = foreignChannel
						}
						payload := map[string]any{}
						switch request.Params.Name {
						case "slack_search_channels":
							payload["results"] = "### Result 1\nChannel ID: " + channelID + "\nName: test\nIs Private: false"
						case "slack_search_users":
							if collision == "user" {
								payload["results"] = "### Result 1\nUser ID: " + foreignUser + "\nName: test"
							}
						case "slack_read_channel":
							payload["messages"] = "Channel: test (" + channelID + ")"
							if collision == "message" {
								// Admission now rejects this foreign header before either
								// message can reach persistence.
								payload["messages"] = "Channel: test (" + foreignChannel + ")\n\n=== Message from test (" + foreignUser + ") at 2024-03-09T16:00:00Z === \nMessage TS: 1710000000.000002\n" + canary + "\n\n=== Message from test (" + foreignUser + ") at 2024-03-09T16:00:00Z === \nMessage TS: 1710000000.000001\n" + canary
							}
						default:
							t.Fatalf("unexpected tool %q", request.Params.Name)
						}
						raw, err := json.Marshal(payload)
						require.NoError(t, err)
						result = map[string]any{"content": []map[string]any{{"type": "text", "text": string(raw)}}}
					default:
						t.Fatalf("unexpected method %q", request.Method)
					}
					require.NoError(t, json.NewEncoder(w).Encode(map[string]any{"jsonrpc": "2.0", "id": 1, "result": result}))
				}))
				defer server.Close()
				cfg.Slack.MCP.Enabled = true
				cfg.Slack.MCP.BaseURL = server.URL
				cfg.Slack.MCP.TokenEnv = "SLACRAWL_MCP_DIAGNOSTIC_TOKEN"
				cfg.Slack.MCP.ConnectorID = ""
				t.Setenv("SLACRAWL_MCP_DIAGNOSTIC_TOKEN", "synthetic-token")
				configPath := filepath.Join(dir, "config.toml")
				require.NoError(t, cfg.Save(configPath))
				var stdout, stderr bytes.Buffer
				app := &App{Stdout: &stdout, Stderr: &stderr}
				err = app.Run(ctx, []string{"--config", configPath, "sync", "--source", source, "--workspace", "TREQUEST", "--full"})
				if collision == "message" {
					require.ErrorContains(t, err, "does not match requested conversation")
				} else {
					require.ErrorContains(t, err, "workspace identity conflict")
				}
				output := fmt.Sprint(err) + stdout.String() + stderr.String()
				for _, value := range []string{foreignWorkspace, foreignChannel, foreignUser, "TREQUEST", canary} {
					require.NotContains(t, output, value)
				}
				st, err = store.OpenReadOnly(cfg.DBPath)
				require.NoError(t, err)
				defer func() { require.NoError(t, st.Close()) }()
				for table, prior := range before {
					rows, err := st.QueryReadOnly(ctx, "select * from "+table)
					require.NoError(t, err)
					if table == "sync_state" && collision == "message" {
						require.Len(t, rows, len(prior)+1)
						var retained []map[string]any
						for _, row := range rows {
							if row["entity_type"] != store.MCPHistoryEntityType {
								retained = append(retained, row)
								continue
							}
							value, ok := row["value"].(string)
							require.True(t, ok)
							var progress store.MCPHistoryState
							require.NoError(t, json.Unmarshal([]byte(value), &progress))
							require.NotEmpty(t, progress.Revision)
							require.Equal(t, store.MCPHistoryState{Pending: new(""), Revision: progress.Revision}, progress)
							updated, ok := row["updated_at"].(string)
							require.True(t, ok)
							_, parseErr := time.Parse(time.RFC3339Nano, updated)
							require.NoError(t, parseErr)
							require.Equal(t, map[string]any{"source_name": "mcp", "entity_type": store.MCPHistoryEntityType, "entity_id": `["TREQUEST","CLOCAL","codex",""]`, "value": value, "updated_at": updated}, row)
						}
						rows = retained
					}
					require.ElementsMatch(t, prior, rows, table)
				}
			})
		}
	}
}
